INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  'a5540c6a-b4b8-441e-a359-64673c18873b', 'burger-bliss-uae-by-grandiose-brand-identity-design', 'BURGER BLISS UAE BY GRANDIOSE', 'Dubai, UAE', '',
  'Hospitality', '2025', 'BURGER BLISS UAE BY GRANDIOSE', '', 'Completed',
  '', '["Branding","F&B Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'At TwentyOne06, we were tasked with transforming Burger Bliss from a supermarket brand into a standalone restaurant in Abu Dhabi with its own unique identity. Our challenge was to build a brand that could compete in the UAE’s vibrant F&B scene while reflecting the multicultural community it serves. From redefining the brand story and mission to creating a vibrant visual identity, tone of voice, and digital presence, we approached the project as a full-scale rebrand and brand evolution. Making Burger Bliss more than just a meal, but a destination experience.', 'Our strategy focused on creating a cohesive brand that celebrates global flavors and multicultural connections. We redefined the brand story, tone of voice, and visual identity, developing a logo, color palette, packaging, and digital assets that reflect the energy and inclusivity of the UAE audience. The interior design extends this identity into the physical space, with community-focused layouts, vibrant materials, and integrated branding that encourage connection and enhance the dining experience.',
  'The result is a modern, immersive brand and space that turns Burger Bliss into a destination, not just a meal, for Abu Dhabi’s diverse community.', 'At TwentyOne06, we were tasked with transforming Burger Bliss from a supermarket brand into a standalone restaurant in Abu Dhabi with its own unique identity. Our challenge was to build a brand that could compete in the …', '["At TwentyOne06, we were tasked with transforming Burger Bliss from a supermarket brand into a standalone restaurant in Abu Dhabi with its own unique identity. Our challenge was to build a brand that could compete in the UAE’s vibrant F&B scene while reflecting the multicultural community it serves. From redefining the brand story and mission to creating a vibrant visual identity, tone of voice, and digital presence, we approached the project as a full-scale rebrand and brand evolution. Making Burger Bliss more than just a meal, but a destination experience.","Our strategy focused on creating a cohesive brand that celebrates global flavors and multicultural connections. We redefined the brand story, tone of voice, and visual identity, developing a logo, color palette, packaging, and digital assets that reflect the energy and inclusivity of the UAE audience. The interior design extends this identity into the physical space, with community-focused layouts, vibrant materials, and integrated branding that encourage connection and enhance the dining experience.","The result is a modern, immersive brand and space that turns Burger Bliss into a destination, not just a meal, for Abu Dhabi’s diverse community.","The Burger Bliss rebrand involved a complete transformation of the logo to signify its evolution from a supermarket product to a standalone restaurant. The original logo was monochrome,  featuring a hand-drawn burger and rounded type, but it lacked distinction and scalability for an elevated brand.","The new logo, however, features bold, modern typography that communicates a premium yet approachable quality. It is flexible for use on signage, packaging, and digital platforms, reflecting the shift to a destination experience for a multicultural community. This new logo serves as a visual anchor for the brand, enhancing cohesion across color, typography, packaging, and interior design to create an immersive experience.","The brand pattern for Burger Bliss was inspired by the UAE’s global community, a melting pot of cultures, stories, and flavors that come together at the table. Rooted in the concept of “Global Community,” the pattern reflects the brand’s mission to unite people through shared moments. Drawing from South Asian patterns, Japanese painted effects, Arabic calligraphy, and Mexican pyramids, we created a fusion of global influences that celebrates diversity while feeling contemporary and handcrafted.","The result is a pattern that embodies the spirit of the UAE: modern, multicultural, and full of character. It extends across packaging, menus, and interiors, becoming a visual symbol of Burger Bliss’s story: bringing people together through food.","The Burger Bliss brand icon represents the idea of cultures coming together, visually forming the perfect “burger.” Each layer symbolizes the blending of global influences that define the UAE’s multicultural spirit. We used the brand pattern to shape the burger’s bun and patty, merging South Asian and Arabic motifs into one cohesive form. This approach transforms a simple burger into a symbol of community and craft, where design becomes a storytelling tool."]'::jsonb, '/projects/burger-bliss-uae-by-grandiose-brand-identity-design-burger-bliss-uae-brand-identity-design-by-twentyone06-scaled-1-b400306b.png', '["/projects/burger-bliss-uae-by-grandiose-brand-identity-design-burger-bliss-uae-brand-identity-design-by-twentyone06-scaled-88a18881.png","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-c02-scaled-8cb3210f.jpg","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-screenshot-2025-10-07-102249-82cd74cf.png","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-burger-bliss-uae-brand-pattern-design-by-twentyone06-00de5bac.png","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-burger-bliss-uae-brand-identity-design-by-twentyone06-1-b32c998b.png","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-burger-bliss-uae-menu-design-by-twentyone06-1-b025926e.png","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-1-1-81f0a405.png","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-2-1-9a64a8c2.png","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-3-1-20a8bb2f.png","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-12-11ed87d7.png","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-4-1-eb20c820.png","/projects/burger-bliss-uae-by-grandiose-brand-identity-design-6-af6323eb.png"]'::jsonb,
  'tall', '["branding","interior-design"]'::jsonb, true, 0, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  '7e822e3f-c73f-457d-ad1a-219be7205d42', 'cheese-board-by-grandiose', 'CHEESE BOARD BY GRANDIOSE', 'Dubai, UAE', '',
  'Hospitality', '2025', 'CHEESE BOARD BY GRANDIOSE', '', 'Completed',
  '', '["Branding","F&B Design","Retail Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'Cheese Board’s new flagship on Bluewaters Island is not a grocery store wearing theatrical lights. It’s a stage. Commissioned by Grandiose and reimagined by TwentyOne06, the 1,126 sq ft (104.6 sq m) interior translates cheesemaking into a rebranded architecture, materiality, and choreography - reframing product, pedagogy and retail into a single, sensory performance. Not just a rebrand, it’s a supermarket-born concept transformed into a standalone cultural destination.', 'Our strategy focused on creating a cohesive brand that celebrates global flavors and multicultural connections. We redefined the brand story, tone of voice, and visual identity, developing a logo, color palette, packaging, and digital assets that reflect the energy and inclusivity of the UAE audience. The interior design extends this identity into the physical space, with community-focused layouts, vibrant materials, and integrated branding that encourage connection and enhance the dining experience.',
  'The result is a modern, immersive brand and space that turns Burger Bliss into a destination, not just a meal, for Abu Dhabi’s diverse community.', 'Cheese Board’s new flagship on Bluewaters Island is not a grocery store wearing theatrical lights. It’s a stage. Commissioned by Grandiose and reimagined by TwentyOne06, the 1,126 sq ft (104.6 sq m) interior translates c…', '["Cheese Board’s new flagship on Bluewaters Island is not a grocery store wearing theatrical lights. It’s a stage. Commissioned by Grandiose and reimagined by TwentyOne06, the 1,126 sq ft (104.6 sq m) interior translates cheesemaking into a rebranded architecture, materiality, and choreography - reframing product, pedagogy and retail into a single, sensory performance. Not just a rebrand, it’s a supermarket-born concept transformed into a standalone cultural destination.","Our strategy focused on creating a cohesive brand that celebrates global flavors and multicultural connections. We redefined the brand story, tone of voice, and visual identity, developing a logo, color palette, packaging, and digital assets that reflect the energy and inclusivity of the UAE audience. The interior design extends this identity into the physical space, with community-focused layouts, vibrant materials, and integrated branding that encourage connection and enhance the dining experience.","The result is a modern, immersive brand and space that turns Burger Bliss into a destination, not just a meal, for Abu Dhabi’s diverse community.","Cheese Board is about creating a masterpiece on a charcuterie board. Cheese making is an age-old craft through which we aim to tell a story with every selection. This is where cheese making meets fine art, where it meets history and tradition, where each flavor is a note, each pairing of cheeses - a chord, each tasting event - a performance. Our artisans are like painters with their palettes or composers with their symphonies.","It is Cheese Board’s first independent store outside the Grandiose supermarket network, designed to stand alone as a premium destination on Bluewaters Island. The ambition demanded more than identity work - it required an environment sophisticated enough for Dubai’s most cosmopolitan visitors, while still retaining accessibility and approachability. This is a design-first project that treats cheese as the protagonist, design as the stagecraft, and the guest as an intentional audience. The outcome is a premium, approachable “Gallery of Taste” where rare wheels and humble wedges are displayed, explained and celebrated as cultural artifacts.","This logo concept is vaguely inspired by classic crest-style designs, but in a more modern way. It includes hand-sketched images of a wooden board and the King of cheese - Parmesan, to accentuate the idea of Art, with clean serif fonts.","Crucially, the design is commercial by intent. The merchandising strategy, 70% display devoted to cheese, ensures that visual merchandising itself becomes the primary sales driver. Rotating premium showcases and The Vault create a cadence of scarcity and novelty that incentivises return visits. The Curation counter functions as an upsell engine: personalized boards, paired drinks, and guided service increase average spend and deepen brand loyalty. This is designed as a business strategy: spatial sequencing encourages discovery, premium materiality justifies price, and intimate programming (tastings, workshops) converts customers into a community.","A Five-Act Experience The floorplan was designed as a sequential performance that guides guests through discovery, retail, rarity, personalization, and community. From tasting stations and curated displays to a vault for rare cheeses, bespoke board curation, and cultural activations, each zone is crafted to deepen engagement, extend dwell time, and turn visits into lasting relationships."]'::jsonb, '/projects/cheese-board-by-grandiose-cheese-board-by-twentyone06-3-1-05ccbf6c.png', '["/projects/cheese-board-by-grandiose-burger-bliss-uae-brand-identity-design-by-twentyone06-scaled-88a18881.png","/projects/cheese-board-by-grandiose-cheeseboard-2-scaled-a38cea93.jpg","/projects/cheese-board-by-grandiose-screenshot-2025-09-15-151015-1236f6b6.png","/projects/cheese-board-by-grandiose-screenshot-2025-09-15-152242-7911915c.png","/projects/cheese-board-by-grandiose-cheese-board-brand-design-by-twentyone06-3-ae3be5c0.png","/projects/cheese-board-by-grandiose-cheese-board-brand-design-by-twentyone06-12-e5b13bfa.png","/projects/cheese-board-by-grandiose-cheese-board-brand-design-by-twentyone06-11-1c789dec.png","/projects/cheese-board-by-grandiose-cheese-board-brand-design-by-twentyone06-10-3c834928.png","/projects/cheese-board-by-grandiose-cheese-board-brand-design-by-twentyone06-9-7403f133.png","/projects/cheese-board-by-grandiose-cheese-board-brand-design-by-twentyone06-8-fe94b0b3.png","/projects/cheese-board-by-grandiose-cheese-board-brand-design-by-twentyone06-7-2f9ec104.png","/projects/cheese-board-by-grandiose-cheese-board-brand-design-by-twentyone06-6-67f8f202.png"]'::jsonb,
  'short', '["branding","interior-design"]'::jsonb, true, 1, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  'c4bd8e99-de8d-45af-a008-c4571a8a426c', 'dental-nation-acacia-clinic', 'DENTAL NATION', 'Dubai, UAE', '',
  'Commercial', '2025', 'DENTAL NATION', '', 'Completed',
  '', '["Commercial Design","Healthcare Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'The renovation of Dental Nation involved renovating a polyclinic into a specialized dental clinic that exudes Quiet Luxury. The goal was to create a serene and refined environment that enhances patient experience while reinforcing the brand’s identity. By integrating high-quality materials, soft neutral tones, and a sophisticated yet welcoming ambiance, the new design aims to attract new clients while maintaining loyalty among existing patients.', 'The design concept revolves around Quiet Luxury, which is defined by elevated simplicity and timeless elegance. The space was designed to be visually calming, using natural materials, clean lines, and a muted color palette to establish a high-end yet approachable atmosphere. Soft greens and warm neutrals promote a sense of relaxation, reducing anxiety and ensuring a pleasant patient journey.',
  'To create a strong and recognizable brand identity, the new interior design of Dental Nation needed to be distinct yet functional. The approach focused on: Establishing a clear brand presence that signals transformation and quality. Encouraging new clientele while retaining existing patients. Using a refined material palette to enhance elegance, transparency, and comfort. Creating a seamless patient journey through open, luminous, and well-defined spaces.', 'The renovation of Dental Nation involved renovating a polyclinic into a specialized dental clinic that exudes Quiet Luxury. The goal was to create a serene and refined environment that enhances patient experience while r…', '["The renovation of Dental Nation involved renovating a polyclinic into a specialized dental clinic that exudes Quiet Luxury. The goal was to create a serene and refined environment that enhances patient experience while reinforcing the brand’s identity. By integrating high-quality materials, soft neutral tones, and a sophisticated yet welcoming ambiance, the new design aims to attract new clients while maintaining loyalty among existing patients.","The design concept revolves around Quiet Luxury, which is defined by elevated simplicity and timeless elegance. The space was designed to be visually calming, using natural materials, clean lines, and a muted color palette to establish a high-end yet approachable atmosphere. Soft greens and warm neutrals promote a sense of relaxation, reducing anxiety and ensuring a pleasant patient journey.","To create a strong and recognizable brand identity, the new interior design of Dental Nation needed to be distinct yet functional. The approach focused on: Establishing a clear brand presence that signals transformation and quality. Encouraging new clientele while retaining existing patients. Using a refined material palette to enhance elegance, transparency, and comfort. Creating a seamless patient journey through open, luminous, and well-defined spaces.","The Reception Area acts as the first impression and embodies the Quiet Luxury concept. A bespoke L-shaped sofa upholstered in soft mint green and light beige. A reception desk with slatted panels in mint green for a warm yet structured aesthetic. Micro quartz coarse base for a refined touch that reinforces durability and sophistication.","Our latest dental clinic refurbishment strips away the clinical clichés in favor of a soft, serene minimalism that puts patients at ease from the moment they walk in. Warm neutrals, seamless transitions, and diffused lighting create a space that feels like a wellness retreat, because healthcare should feel human.","Minimalistic and streamlined with integrated lighting to ensure a hygienic, professional environment. The Dental Rooms are designed with soft natural tones, fostering a serene and elegant atmosphere.","The renovation of Dental Nation successfully elevated the brand’s perception, reinforcing its identity as a specialized dental clinic that prioritizes patient comfort, high-end service, and aesthetic excellence.","- Improved client retention by enhancing the environment for returning patients."]'::jsonb, '/projects/dental-nation-acacia-clinic-dental-nation-interior-design-by-twentyone06-12-scaled-ccf2e735.jpg', '["/projects/dental-nation-acacia-clinic-dental-nation-interior-design-by-twentyone06-12-scaled-ccf2e735.jpg"]'::jsonb,
  'wide', '["interior-design"]'::jsonb, true, 2, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  'd2a195a0-6766-4e86-a41c-3f03496c1b2d', 'flaky-pastry-the-galleria', 'FLAKY PASTRY - THE GALLERIA', 'Dubai, UAE', '',
  'Hospitality', '2025', 'FLAKY PASTRY - THE GALLERIA', '', 'Completed',
  '', '["F&B Design","Hospitality Design","Retail Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'F&B Design - Hospitality Design - Retail Design', 'TwentyOne06 has brought a distinctly narrative-driven approach to the third branch of Flaky Pastry Croissant Company, located in The Galleria Al Maryah Island in Abu Dhabi. This 159 sqm croissanterie is the brand’s first venture outside Dubai and serves as a showcase of how food, form, and space can intersect to create a cohesive, multisensory experience. Known for its design-led hospitality work, TwentyOne06 has taken Flaky Pastry’s artisanal ethos and translated it into spatial gestures that reflect the very process of croissant-making.',
  'The concept focuses on the anatomy and process of croissant-making, highlighted by five key design moments. The stone-effect counter fascia mimics pastry flour, symbolizing the raw starting point. Textured linear walls and fluted finishes reflect the triangular cuts of rolled dough. Curved wooden benches and wall textures mirror the crescent shapes of baked croissants. A fabric ceiling installation with gradient materials represents the airy, layered interior of a croissant.', 'F&B Design - Hospitality Design - Retail Design', '["F&B Design - Hospitality Design - Retail Design","TwentyOne06 has brought a distinctly narrative-driven approach to the third branch of Flaky Pastry Croissant Company, located in The Galleria Al Maryah Island in Abu Dhabi. This 159 sqm croissanterie is the brand’s first venture outside Dubai and serves as a showcase of how food, form, and space can intersect to create a cohesive, multisensory experience. Known for its design-led hospitality work, TwentyOne06 has taken Flaky Pastry’s artisanal ethos and translated it into spatial gestures that reflect the very process of croissant-making.","The concept focuses on the anatomy and process of croissant-making, highlighted by five key design moments. The stone-effect counter fascia mimics pastry flour, symbolizing the raw starting point. Textured linear walls and fluted finishes reflect the triangular cuts of rolled dough. Curved wooden benches and wall textures mirror the crescent shapes of baked croissants. A fabric ceiling installation with gradient materials represents the airy, layered interior of a croissant.","For the third location of Flaky Pastry Croissant Company , and its first outside of Dubai, UAE-based design studio TwentyOne06 has crafted more than just an interior, it is a sensorial narrative built around the artisanal journey of croissants. Located at The Galleria Al Maryah Island, this 159 sqm space offers a refined, spatial expression of Flaky Pastry’s brand DNA: gourmet laminated doughs, bold visuals, and a passion for craft.","Best known for their narrative-first hospitality design, TwentyOne06 approached this project with a simple premise: the croissant becomes the architecture.","Flaky Pastry was recognised at the Commercial Interior Design Awards 2025 - Hospitality with a double honour - winning Best Use of Materials and receiving a Highly Commended for Best Casual Restaurant Design .","This project celebrates our obsessive attention to detail, where materiality, mood, and narrative come together to create an experience that feels both elevated and effortless. A true showcase of our storytelling-led design approach.","Flaky Pastry’s ethos centers around celebrating artisanal pastry-making, and the layout reinforces this focus. From outside the store, customers are drawn in through a clear view of the pastry counter and the chef at work, framed by a curved glazed façade with frosted gradient glass that mimics the warming tones of a croissant in the oven."]'::jsonb, '/projects/flaky-pastry-the-galleria-flaky-pastry-by-twentyone06-9-scaled-1d813945.jpg', '["/projects/flaky-pastry-the-galleria-4e03bc9a-572c-4e31-bc0b-949820969b29-rijsi2j3iw9i5pswyrq0rdlwvg7g19sobdew7nu9s0-b20c39ed.png","/projects/flaky-pastry-the-galleria-a272ee91-9c9b-4705-bac8-e473081d13ef-rijsia1t1kjsqlhzquz1bbplmj6dqumj0ems1vj4e8-da52c6d4.png","/projects/flaky-pastry-the-galleria-screenshot-2025-05-06-112853-rijsia1yw2ppot6mkbdgyf8py81259oyu3ba4kqcpk-67adf0a5.png","/projects/flaky-pastry-the-galleria-screenshot-2025-05-06-113018-432763d0.png","/projects/flaky-pastry-the-galleria-screenshot-2025-05-06-113419-1dca32df.png","/projects/flaky-pastry-the-galleria-screenshot-2025-05-06-115809-97c44468.png"]'::jsonb,
  'tall', '["interior-design"]'::jsonb, true, 3, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  '850ef5c6-9226-439b-a40a-56c22e1b36cd', 'the-knowledge-academy-training-centre', 'THE KNOWLEDGE ACADEMY - TRAINING CENTRE', 'Dubai, UAE', '',
  'Commercial', '2025', 'THE KNOWLEDGE ACADEMY - TRAINING CENTRE', '', 'Completed',
  '', '["Commercial Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'Following the successful design of The Knowledge Academy''s main office, our team at TwentyOne06, in partnership with fit-out giants, Havelock One, was brought back to reimagine their newest training center, a 300 sqm space located in I-Rise Tower, Barsha Heights, Dubai.', 'This resimercial workspace design was about continuing a design language that feels warm, elevated, and deeply considered. Designed as a counterpart to their primary workspace, this new environment was designed with a hospitality-first mindset, tailored for focus, productivity, and experience.',
  'Inspired by hospitality interiors, the design approach embraces the resimercial trend, melding residential warmth with commercial sophistication. The use of plush textures, soft lighting, and elegant materials creates an inviting workspace that feels refined yet approachable. A harmonious blend of natural wood, Statuario marble, and brass accents reinforces the luxurious yet functional aesthetic.', 'Following the successful design of The Knowledge Academy''s main office, our team at TwentyOne06, in partnership with fit-out giants, Havelock One, was brought back to reimagine their newest training center, a 300 sqm spa…', '["Following the successful design of The Knowledge Academy''s main office, our team at TwentyOne06, in partnership with fit-out giants, Havelock One, was brought back to reimagine their newest training center, a 300 sqm space located in I-Rise Tower, Barsha Heights, Dubai.","This resimercial workspace design was about continuing a design language that feels warm, elevated, and deeply considered. Designed as a counterpart to their primary workspace, this new environment was designed with a hospitality-first mindset, tailored for focus, productivity, and experience.","Inspired by hospitality interiors, the design approach embraces the resimercial trend, melding residential warmth with commercial sophistication. The use of plush textures, soft lighting, and elegant materials creates an inviting workspace that feels refined yet approachable. A harmonious blend of natural wood, Statuario marble, and brass accents reinforces the luxurious yet functional aesthetic.","TwentyOne06’s expertise in spatial storytelling ensures that each design element is intentional, catering to the needs of modern professionals who seek both comfort and a premium office experience.","TwentyOne06 approached the spatial layout with precision, maximising the number of training rooms and workstations while maintaining an open, airy feel. The integration of a radial layout, with curved spaces that guide movement organically, posed a unique challenge but ultimately created a fluid, cohesive environment.","Every element of the design was carefully considered to balance functionality and comfort, resultin in a space that is both intuitive to navigate to navigate and offers a sense of openness. Lighting, a key factor of the design, plays a pivotal role in boosting productivity. Overhead lighting, supplied by Lylux Lighting, was strategically positioned to provide optimal lux levels for both learning and working, ensuring a comfortable visual experience throughout the day.","The choice of materials was crucial in creating a workspace that is both luxurious and durable. Luxury vinyl tile (LVT) flooring, chosen for its warmth and durability, replicates the richness of natural wood while being resilient enough to withstand high foot traffic. The combination of textured white walls, brushed brass accents, and acoustic panels in a subtle blush tone, derived from the brand’s colour palette, elevates the space with premium yet welcoming aesthetic. These elements seamlessly blend together to create a visually striking, harmonious that exudes sophistication and approachability.","Having previously designed the Knowledge Academy’s main office, TwentyOne06 ensured that the training center remained an extension of the brand’s identity while adapting to its distinct purpose. While the head office is designed to support daily operations and collaboration, this space is purpose-built for skill development, fostering focus and concentration, all while preserving the same premium aesthetic that defines the brand."]'::jsonb, '/projects/the-knowledge-academy-training-centre-irise-training-centre-by-twentyone06-4-scaled-b6188e9b.jpg', '["/projects/the-knowledge-academy-training-centre-design-middle-east-logo-rijsia1t1kjsqlhzquz1bbplmj6dqumj0ems1vj4e8-e9cef55f.png","/projects/the-knowledge-academy-training-centre-love-that-design-logo-2-rijsia1t1kjsqlhzquz1bbplmj6dqumj0ems1vj4e8-37679906.png","/projects/the-knowledge-academy-training-centre-office-snapshots-logo-rijsia1t1kjsqlhzquz1bbplmj6dqumj0ems1vj4e8-7a2c6484.png","/projects/the-knowledge-academy-training-centre-80e242b6-3dff-4323-8ff5-776927378ce7-rijsi2j3iw9i5pswyrq0rdlwvg7g19sobdew7nu9s0-e5bc2aa1.png"]'::jsonb,
  'short', '["interior-design"]'::jsonb, false, 4, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  '0d7e946a-1cdc-475c-a2f9-ca153421f243', 'mari-vanna-dubai', 'MARI VANNA DUBAI', 'Dubai, UAE', '',
  'Hospitality', '2025', 'MARI VANNA DUBAI', '', 'Completed',
  '', '["F&B Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'A reimagining of Mari Vanna in Dubai, this design concept pays homage to the grandeur of 19th-century Russian noble estates, immersing guests in an atmosphere of opulence, nostalgia, and warmth. The new concept strengthens Mari Vanna’s identity as an authentic Russian dining experience, combining rich architectural details, vintage decor, and traditional elements to transport guests to a bygone era.', 'Inspired by the stately homes of 19th-century Russian aristocracy, the design embraces grand architectural features, luxurious materials, and ornate detailing. A mix of antique furniture, intricate wallpaper, and traditional Russian artwork enhances authenticity, while elements like a cozy fireplace, delicate lace curtains, and handcrafted decor evoke the charm of a Russian grandmother’s home.',
  'The culinary experience is elevated through immersive thematic events, from live traditional music to vodka tastings, reinforcing Mari Vanna as a cultural and gastronomic destination.', 'A reimagining of Mari Vanna in Dubai, this design concept pays homage to the grandeur of 19th-century Russian noble estates, immersing guests in an atmosphere of opulence, nostalgia, and warmth. The new concept strengthe…', '["A reimagining of Mari Vanna in Dubai, this design concept pays homage to the grandeur of 19th-century Russian noble estates, immersing guests in an atmosphere of opulence, nostalgia, and warmth. The new concept strengthens Mari Vanna’s identity as an authentic Russian dining experience, combining rich architectural details, vintage decor, and traditional elements to transport guests to a bygone era.","Inspired by the stately homes of 19th-century Russian aristocracy, the design embraces grand architectural features, luxurious materials, and ornate detailing. A mix of antique furniture, intricate wallpaper, and traditional Russian artwork enhances authenticity, while elements like a cozy fireplace, delicate lace curtains, and handcrafted decor evoke the charm of a Russian grandmother’s home.","The culinary experience is elevated through immersive thematic events, from live traditional music to vodka tastings, reinforcing Mari Vanna as a cultural and gastronomic destination.","The interior showcases a rich layering of textures and materials, creating a space that feels both elegant and inviting. The mirror wall paneling with brass accents, ornate moldings, and vintage chandeliers lend an air of aristocratic grandeur.","A delicate balance of warm lighting, antique decorative pieces, and curated memorabilia ensures that every corner of the space tells a story. The bar area and outdoor space are redefined, blending functionality with a signature aesthetic that complements the overall Russian estate narrative.","At the heart of the design is the traditional Russian fireplace, a symbolic and functional centerpiece that radiates warmth and nostalgia. Cladded in classic blue-and-white floral tiles, the fireplace evokes the ambiance of a historic Russian home, making it a key element in establishing Mari Vanna’s welcoming and homely charm.","The bar area becomes a standout feature, designed with high-back shelving, mirrored backs, and warm lighting to create a visually striking and inviting focal point. The marble countertop with brass trim, wooden panels with moldings, and blue bar stools with brass accents elevate the space, blending luxury with a timeless aesthetic.","Large central outdoor table with loose decor"]'::jsonb, '/projects/mari-vanna-dubai-website-cover-1-1fd572aa.png', '["/projects/mari-vanna-dubai-website-cover-1-1fd572aa.png"]'::jsonb,
  'wide', '["interior-design"]'::jsonb, false, 5, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  'dbb1b868-abb0-4062-a07c-b7d678448431', 'the-observatory-lounge-the-prime-52', 'THE OBSERVATORY LOUNGE & PRIME 52', 'Dubai, UAE', '',
  'Hospitality', '2025', 'THE OBSERVATORY LOUNGE & PRIME 52', '', 'Completed',
  '', '["Branding","F&B Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'The Observatory Lounge is a legacy restaurant in Dubai, renowned for its steakhouse excellence and 360-degree panoramic views. Over its 15-year history, it has witnessed the city’s transformation but has also lost part of its identity, atmosphere, and functionality. The goal of this restaurant renovation is to revive its brand presence, ensuring it remains a standout destination while retaining loyal customers and attracting new clientele.', 'The redesign takes inspiration from what an observatory does, TO OBSERVE.',
  'The space will be reimagined with focal points throughout its 360-degree layout, guiding guests through a curated visual experience. Light will play a central role, with natural and specialty lighting setups used to enhance the atmosphere.', 'The Observatory Lounge is a legacy restaurant in Dubai, renowned for its steakhouse excellence and 360-degree panoramic views. Over its 15-year history, it has witnessed the city’s transformation but has also lost part o…', '["The Observatory Lounge is a legacy restaurant in Dubai, renowned for its steakhouse excellence and 360-degree panoramic views. Over its 15-year history, it has witnessed the city’s transformation but has also lost part of its identity, atmosphere, and functionality. The goal of this restaurant renovation is to revive its brand presence, ensuring it remains a standout destination while retaining loyal customers and attracting new clientele.","The redesign takes inspiration from what an observatory does, TO OBSERVE.","The space will be reimagined with focal points throughout its 360-degree layout, guiding guests through a curated visual experience. Light will play a central role, with natural and specialty lighting setups used to enhance the atmosphere.","This approach will modernize the brand while respecting its heritage, reinforcing its identity as an iconic dining destination in Dubai.","Zoning the space into distinct areas: Bar, Dining, and Lounge, each offering a unique atmosphere.  Layering light strategically, combining natural light from the panoramic windows with specialty lighting to highlight key moments.","Incorporating brand storytelling, the Observatory has been a silent witness to Dubai’s growth, and this history will be woven into the guest journey.","Enhancing brand elements, introducing a new logo, colors, and branded collateral to reinforce a strong visual identity.","The wine bar at Prime 52 will create an atmospheric setting that highlights both wine and meat. A prominent bar will serve as a central feature, equipped with adjustable seating options. This space will embody a mid to premium theatrical vibe, showcasing the product, wine, as the star attraction."]'::jsonb, '/projects/the-observatory-lounge-the-prime-52-website-cover-8f8ba9bf.png', '["/projects/the-observatory-lounge-the-prime-52-a272ee91-9c9b-4705-bac8-e473081d13ef-rijsia1t1kjsqlhzquz1bbplmj6dqumj0ems1vj4e8-da52c6d4.png","/projects/the-observatory-lounge-the-prime-52-29257e5e-aa26-400f-a032-6aef4c9a23b0-rijsi2j3iw9i5pswyrq0rdlwvg7g19sobdew7nu9s0-ef4130bb.png","/projects/the-observatory-lounge-the-prime-52-1-35414360.png","/projects/the-observatory-lounge-the-prime-52-45-16-bafe8c92.png","/projects/the-observatory-lounge-the-prime-52-5-6d336015.png","/projects/the-observatory-lounge-the-prime-52-3-16c125b5.png","/projects/the-observatory-lounge-the-prime-52-2-1-79ea8b4f.png","/projects/the-observatory-lounge-the-prime-52-4-a537f56d.png"]'::jsonb,
  'tall', '["branding","interior-design"]'::jsonb, false, 6, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  '425dfb24-6f9c-4848-a7ee-5b7d1aa8dd49', 'tokyo-arabia', 'Tokyo Arabia', 'Dubai, UAE', '',
  'Hospitality', '2025', 'Tokyo Arabia', '', 'Completed',
  '', '["F&B Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'Tokyo Arabia is a premier fine-dining Japanese restaurant in Saudi Arabia, seamlessly blending tradition with contemporary sophistication. By integrating traditional Japanese design principles with sleek, modern materials, we created an immersive dining experience that balances elegance and authenticity. The result is a refined, high-end space that positions Tokyo Arabia as a leader in luxury dining.', 'The Tokyo brand was well-recognized but visually flat. We added depth and layers to its design language, reinforcing its visual impact and creating a more immersive environment.

 We blended traditional Japanese construction techniques with contemporary materials, achieving a striking balance between heritage and modernity.

 The dining and sushi areas were designed to be adaptable, catering to different guest experiences. Whether for quick single seating or comfortable long dining sessions, the space is fluid and responsive.',
  'A unique and partially concealed mocktail bar was introduced, adding an intimate and exclusive layer to the dining atmosphere. The secret mocktail bar surrounded by lush greenery and water features offers an exclusive and intimate retreat within the restaurant. This hidden gem enhances the experiential nature of the space, encouraging repeat visits and exploration.', 'Tokyo Arabia is a premier fine-dining Japanese restaurant in Saudi Arabia, seamlessly blending tradition with contemporary sophistication. By integrating traditional Japanese design principles with sleek, modern material…', '["Tokyo Arabia is a premier fine-dining Japanese restaurant in Saudi Arabia, seamlessly blending tradition with contemporary sophistication. By integrating traditional Japanese design principles with sleek, modern materials, we created an immersive dining experience that balances elegance and authenticity. The result is a refined, high-end space that positions Tokyo Arabia as a leader in luxury dining.","The Tokyo brand was well-recognized but visually flat. We added depth and layers to its design language, reinforcing its visual impact and creating a more immersive environment.\n\n We blended traditional Japanese construction techniques with contemporary materials, achieving a striking balance between heritage and modernity.\n\n The dining and sushi areas were designed to be adaptable, catering to different guest experiences. Whether for quick single seating or comfortable long dining sessions, the space is fluid and responsive.","A unique and partially concealed mocktail bar was introduced, adding an intimate and exclusive layer to the dining atmosphere. The secret mocktail bar surrounded by lush greenery and water features offers an exclusive and intimate retreat within the restaurant. This hidden gem enhances the experiential nature of the space, encouraging repeat visits and exploration.","A dedicated tea bar featuring rare imported teas, set against fresh greenery, enhances the sensory journey.","Layered textures and textiles, adding depth and tactile interest.","Teppanyaki - Live cooking and dining area"]'::jsonb, '/projects/tokyo-arabia-tokyo-arabia-alurubah-branch-21-scaled-4ecf8607.jpg', '["/projects/tokyo-arabia-29257e5e-aa26-400f-a032-6aef4c9a23b0-22d57905.png","/projects/tokyo-arabia-a272ee91-9c9b-4705-bac8-e473081d13ef-e9355a05.png","/projects/tokyo-arabia-b1477dfb-0081-4a4f-aa57-f03c4a6bff6b-ba7163d2.png","/projects/tokyo-arabia-tokyo-arabia-alurubah-branch-37-scaled-rijsi78gbklupzaq0s5l8xyc62eyi6drtpctoquj8-23f85525.jpg","/projects/tokyo-arabia-tokyo-arabia-alurubah-branch-23-scaled-b3a22545.jpg"]'::jsonb,
  'short', '["interior-design"]'::jsonb, false, 7, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  'f9886e02-73d0-4fb3-a8eb-6f2f50b6bbff', 'yvonne-dubai-hills', 'YVONNE DUBAI HILLS', 'Dubai, UAE', '',
  'Hospitality', '2025', 'YVONNE DUBAI HILLS', '', 'Completed',
  '', '["F&B Design","Retail Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'Yvonne, a French patisserie in Dubai Hills, was transformed by TwentyOne06 into a bold, maximalist space that breaks away from traditional patisserie aesthetics. Through deep research and design foresight, the team created an immersive, nostalgia-driven environment that stands out in Dubai’s competitive F&B scene.', 'Inspired by maximalism, daring nostalgia, and the emotional power of color, Yvonne Dubai Hills is a vibrant reinterpretation of classic French patisseries.',
  'The space merges bold colors, eclectic patterns, and whimsical design elements to create a sensory-rich environment that feels both playful and luxurious.', 'Yvonne, a French patisserie in Dubai Hills, was transformed by TwentyOne06 into a bold, maximalist space that breaks away from traditional patisserie aesthetics. Through deep research and design foresight, the team creat…', '["Yvonne, a French patisserie in Dubai Hills, was transformed by TwentyOne06 into a bold, maximalist space that breaks away from traditional patisserie aesthetics. Through deep research and design foresight, the team created an immersive, nostalgia-driven environment that stands out in Dubai’s competitive F&B scene.","Inspired by maximalism, daring nostalgia, and the emotional power of color, Yvonne Dubai Hills is a vibrant reinterpretation of classic French patisseries.","The space merges bold colors, eclectic patterns, and whimsical design elements to create a sensory-rich environment that feels both playful and luxurious.","TwentyOne06 embraced a data-driven approach to ensure Yvonne resonated with its audience. By fusing past and present aesthetics, the design blends vintage charm with contemporary boldness, resulting in an atmosphere that is both immersive and engaging.","Layers of texture, color, and artwork create a visually stimulating yet cohesive space.","Maximalist color and pattern application define the space, with vibrant floral patterns, rich pinks, and deep oranges enveloping guests in a sensory experience that challenges traditional patisserie design. The bold hues not only serve as an eye-catching element but also shape the emotional atmosphere of the space.","The nostalgia-infused decor, featuring playful, illustrated mascots and retro design elements, adds character and depth, making the space feel like a journey through different eras of design history. This approach creates a memorable, emotional connection with guests at Yvonne Dubai Hills.","Layered textures and textiles, adding depth and tactile interest."]'::jsonb, '/projects/yvonne-dubai-hills-yvonne-interior-design-by-twentyone06-21-scaled-1c312162.jpg', '["/projects/yvonne-dubai-hills-4e03bc9a-572c-4e31-bc0b-949820969b29-rijsi2j3iw9i5pswyrq0rdlwvg7g19sobdew7nu9s0-b20c39ed.png","/projects/yvonne-dubai-hills-c6b42b24-681f-4791-a649-2b9f70d9eab1-rijsia1t1kjsqlhzquz1bbplmj6dqumj0ems1vj4e8-be41c247.png","/projects/yvonne-dubai-hills-a272ee91-9c9b-4705-bac8-e473081d13ef-rijsia1t1kjsqlhzquz1bbplmj6dqumj0ems1vj4e8-da52c6d4.png","/projects/yvonne-dubai-hills-construction-business-news-rijsi2j3iw9i5pswyrq0rdlwvg7g19sobdew7nu9s0-da97a392.png","/projects/yvonne-dubai-hills-yvonne-interior-design-by-twentyone06-24-scaled-rijsi86aien51l9cvak7tfpsrgabpvhi-7a89a56e.jpg","/projects/yvonne-dubai-hills-yvonne-interior-design-by-twentyone06-40-0e81bb47.jpg","/projects/yvonne-dubai-hills-yvonne-interior-design-by-twentyone06-51-4f6ceabc.jpg","/projects/yvonne-dubai-hills-yvonne-interior-design-by-twentyone06-49-d37ab88f.jpg"]'::jsonb,
  'wide', '["interior-design"]'::jsonb, false, 8, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  '36d85568-02b9-4319-a89e-42d23f8001cd', 'the-knowledge-academy', 'THE KNOWLEDGE ACADEMY', 'Dubai, UAE', '',
  'Commercial', '2025', 'THE KNOWLEDGE ACADEMY', '', 'Completed',
  '', '["Commercial Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'TwentyOne06 has transformed luxury workspace design with The Knowledge Academy''s Dubai office, blending comfort and professionalism. This resimercial space offers a hospitality-driven environment that boosts productivity and well-being through premium materials, craftsmanship, and operational functionality, achieving a balance between opulence and efficiency.', 'Inspired by hospitality interiors, the design approach embraces the resimercial trend, melding residential warmth with commercial sophistication. The use of plush textures, soft lighting, and elegant materials creates an inviting workspace that feels refined yet approachable. A harmonious blend of natural wood, Statuario marble, and brass accents reinforces the luxurious yet functional aesthetic.',
  'TwentyOne06’s expertise in spatial storytelling ensures that each design element is intentional, catering to the needs of modern professionals who seek both comfort and a premium office experience.', 'TwentyOne06 has transformed luxury workspace design with The Knowledge Academy''s Dubai office, blending comfort and professionalism. This resimercial space offers a hospitality-driven environment that boosts productivity…', '["TwentyOne06 has transformed luxury workspace design with The Knowledge Academy''s Dubai office, blending comfort and professionalism. This resimercial space offers a hospitality-driven environment that boosts productivity and well-being through premium materials, craftsmanship, and operational functionality, achieving a balance between opulence and efficiency.","Inspired by hospitality interiors, the design approach embraces the resimercial trend, melding residential warmth with commercial sophistication. The use of plush textures, soft lighting, and elegant materials creates an inviting workspace that feels refined yet approachable. A harmonious blend of natural wood, Statuario marble, and brass accents reinforces the luxurious yet functional aesthetic.","TwentyOne06’s expertise in spatial storytelling ensures that each design element is intentional, catering to the needs of modern professionals who seek both comfort and a premium office experience.","The project’s design philosophy centers on craftsmanship, materiality, and longevity. The office is designed not only to exude exclusivity but also to maintain durability and efficiency in a high-traffic work environment.","By utilizing natural, high-quality materials, such as Glazesupplied natural marble and warm beige wood, the space embodies timeless elegance while ensuring resilience against daily wear and tear. Each material was chosen to enhance the sensory experience, from the tactile richness of wood grain to the cool sophistication of polished marble surfaces.","This design direction ensures that The Knowledge Academy’s office stands as a benchmark for resimercial workspace interiors-both aesthetically compelling and functionally superior. 360-","A defining feature of the office is its meticulously integrated natural marble, reinforcing the high-end aesthetic while ensuring longevity. The entrance corridor walls are clad in polishededge Statuario marble slabs, accentuated by brass partitions that amplify the visual impact. This refined material selection not only expands the perception of space but also establishes an immediate impression of sophistication.","By seamlessly integrating luxury with functionality, TwentyOne06 has designed a workspace that enhances employee experience, operational efficiency, and brand prestige. The Knowledge Academy’s Dubai office now stands as a benchmark for resimercial workspace excellence, embodying a future-forward approach to office design that is both sophisticated and sustainable."]'::jsonb, '/projects/the-knowledge-academy-the-knowledge-academy-identity-awards-2024-2-scaled-ed3d8017.jpg', '["/projects/the-knowledge-academy-design-middle-east-logo-rijsia1t1kjsqlhzquz1bbplmj6dqumj0ems1vj4e8-e9cef55f.png","/projects/the-knowledge-academy-love-that-design-logo-2-rijsia1t1kjsqlhzquz1bbplmj6dqumj0ems1vj4e8-37679906.png","/projects/the-knowledge-academy-office-snapshots-logo-rijsia1t1kjsqlhzquz1bbplmj6dqumj0ems1vj4e8-7a2c6484.png","/projects/the-knowledge-academy-80e242b6-3dff-4323-8ff5-776927378ce7-rijsi2j3iw9i5pswyrq0rdlwvg7g19sobdew7nu9s0-e5bc2aa1.png","/projects/the-knowledge-academy-the-knowledge-academy-identity-awards-2024-8-scaled-rijsi5crxwja2rdgbrcc3yfezao8-c76d5c4f.jpg"]'::jsonb,
  'tall', '["interior-design"]'::jsonb, false, 9, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  '4712c048-1f8d-4df3-a06c-506d66639bcd', 'flow-cafe', 'FLOW CAFE', 'Dubai, UAE', '',
  'Hospitality', '2025', 'FLOW CAFE', '', 'Completed',
  '', '["F&B Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'Flow Café, a dining concept by His Highness Sheikh Mohammed bin Rashid Al Maktoum, is located in Emirates Towers and expanding to Dubai Internet City. Its core values of craft, energy, and sustainability influence a vibrant, adaptable design. Boutique agency TwentyOne06 revitalized the brand''s DNA, ensuring suitability for multiple locations while preserving character and integrity.', 'The design DNA is built around three core
elements:
1. Energy - A bright and inviting ambiance
shaped by pastel tones, natural wood
textures, and abundant greenery,
fostering motivation and productivity.
2. Craft - Every detail is designed to
stimulate creativity and meaningful
conversations, from the unique seating
arrangements to the tactile materials.
3. Sustainability - The integration of ecoconscious
materials, microgreen farming,
and waste-reducing features aligns with
Flow Café’s commitment to the future
of food and environmental responsibility.',
  'This design direction ensures that Flow Café remains an inspiring, adaptable, and franchise-ready brand while reinforcing its core values.', 'Flow Café, a dining concept by His Highness Sheikh Mohammed bin Rashid Al Maktoum, is located in Emirates Towers and expanding to Dubai Internet City. Its core values of craft, energy, and sustainability influence a vibr…', '["Flow Café, a dining concept by His Highness Sheikh Mohammed bin Rashid Al Maktoum, is located in Emirates Towers and expanding to Dubai Internet City. Its core values of craft, energy, and sustainability influence a vibrant, adaptable design. Boutique agency TwentyOne06 revitalized the brand''s DNA, ensuring suitability for multiple locations while preserving character and integrity.","The design DNA is built around three core\nelements:\n1. Energy - A bright and inviting ambiance\nshaped by pastel tones, natural wood\ntextures, and abundant greenery,\nfostering motivation and productivity.\n2. Craft - Every detail is designed to\nstimulate creativity and meaningful\nconversations, from the unique seating\narrangements to the tactile materials.\n3. Sustainability - The integration of ecoconscious\nmaterials, microgreen farming,\nand waste-reducing features aligns with\nFlow Café’s commitment to the future\nof food and environmental responsibility.","This design direction ensures that Flow Café remains an inspiring, adaptable, and franchise-ready brand while reinforcing its core values.","By merging craftsmanship, energy, and sustainability, the space is both functional and aesthetically engaging, designed to elevate the customer experience while staying true to Flow Café’s vision of a future-conscious dining space.","A signature self-service station featuring milk taps dispensing soy, coconut, and oat milk. Additionally, a fresh honey drip display from an open honeycomb reinforces Flow Café’s focus on natural, unprocessed ingredients.","A multi-functional hero piece that serves as seating for casual dining and co-working during the day. At night, it transforms into an auditorium for talks and community events. The design features carved wood detailing and integrated greenery, making it a visually striking focal point.","Natufia Unit\nA low-maintenance microgreen growth unit that supplies fresh, nutrient-rich herbs and produce. This feature reduces the café’s purchasing needs by 20%, cutting reliance on packaged ingredients and aligning with Flow Café’s commitment to future food sustainability."]'::jsonb, '/projects/flow-cafe-thumnail3-81f89994.jpg', '["/projects/flow-cafe-website-project-pages-5-6-26147c37.jpg","/projects/flow-cafe-flow-cafe-by-twentyone06-2-rijsia1z4uha8phim4vxn6xecm3hikbpb6z8dc3a8k-33d810c7.webp"]'::jsonb,
  'short', '["interior-design"]'::jsonb, false, 10, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  'ec223036-0182-4850-a283-0d4b5ca5c344', 'aesthetic-academy', 'AESTHETIC ACADEMY', 'Dubai, UAE', '',
  'Commercial', '2025', 'AESTHETIC ACADEMY', '', 'Completed',
  '', '["Commercial Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'TwentyOne06 designed the Aesthetic Academy to be a premier learning environment dedicated to advancing education in medical aesthetics. The project involved creating state-of-the-art classrooms, labs, seminar rooms, and experiential spaces tailored for both theoretical and practical learning. By integrating high-end design elements with functionality, the academy provides a sophisticated yet immersive experience for students and professionals alike.', 'Commercial/Confidential Dubai Educational',
  'The overarching concept was to create a dynamic learning environment that seamlessly blends medical professionalism with hospitality-driven comfort. The academy’s spaces were strategically planned to facilitate the constant exchange of knowledge while reinforcing the institution’s identity. The design prioritizes flexibility, collaboration, and high-quality finishes to reflect the prestige of the medical aesthetics industry.', 'TwentyOne06 designed the Aesthetic Academy to be a premier learning environment dedicated to advancing education in medical aesthetics. The project involved creating state-of-the-art classrooms, labs, seminar rooms, and …', '["TwentyOne06 designed the Aesthetic Academy to be a premier learning environment dedicated to advancing education in medical aesthetics. The project involved creating state-of-the-art classrooms, labs, seminar rooms, and experiential spaces tailored for both theoretical and practical learning. By integrating high-end design elements with functionality, the academy provides a sophisticated yet immersive experience for students and professionals alike.","Commercial/Confidential Dubai Educational","The overarching concept was to create a dynamic learning environment that seamlessly blends medical professionalism with hospitality-driven comfort. The academy’s spaces were strategically planned to facilitate the constant exchange of knowledge while reinforcing the institution’s identity. The design prioritizes flexibility, collaboration, and high-quality finishes to reflect the prestige of the medical aesthetics industry.","Inspired by the interplay between science and art, the design direction balances clinical precision with an inviting atmosphere.","Neutral, calming color palettes are paired with luxurious materials to establish an environment conducive to learning.","Soft lighting, ergonomic furniture, and acoustically optimized spaces ensure a comfortable and distraction free setting, enhancing both theoretical discussions and hands-on training.","A cutting-edge space equipped with advanced AV technology for lectures, industry talks, and live demonstrations.","A multifunctional communal area designed for discussion, informal learning, and student engagement."]'::jsonb, '/projects/aesthetic-academy-c5-1-35cce342.jpg', '["/projects/aesthetic-academy-c5-1-35cce342.jpg"]'::jsonb,
  'wide', '["interior-design"]'::jsonb, false, 11, true
);
INSERT INTO public.projects (
  id, slug, title, location, price, category, year, client, area, status, duration,
  typologies, scope, materials, finishes, credits, challenge, approach, outcome,
  excerpt, body, hero, gallery, span, services, featured, sort_order, published
) VALUES (
  '3b539915-71ab-4cfb-a5cc-1a6dedaa4179', 'mtn-bayobab', 'MTN/BAYOBAB', 'Dubai, UAE', '',
  'Commercial', '2025', 'MTN/BAYOBAB', '', 'Completed',
  '', '["Commercial Design"]'::jsonb, '[]'::jsonb, '[]'::jsonb,
  '[]'::jsonb, '[{"role":"Studio","name":"TwentyOne06"}]'::jsonb, 'Bayobab’s headquarters, formerly MTN GlobalConnect, required an office space that reflects its evolving brand identity while fostering innovation,
teamwork, and integrity. The design needed to integrate Bayobab’s core values into a functional, inspiring workspace that enhances collaboration and
strengthens the company’s presence.', 'A fusion of Japandi and Industrial design was used to create a balance between warmth, minimalism, and
functionality.',
  'Natural materials, clean LINEAR lines, and soft textures were combined with industrial elements like exposed structures and bold finishes to establish a modern yet welcoming office environment.', 'Bayobab’s headquarters, formerly MTN GlobalConnect, required an office space that reflects its evolving brand identity while fostering innovation,
teamwork, and integrity. The design needed to integrate Bayobab’s core va…', '["Bayobab’s headquarters, formerly MTN GlobalConnect, required an office space that reflects its evolving brand identity while fostering innovation,\nteamwork, and integrity. The design needed to integrate Bayobab’s core values into a functional, inspiring workspace that enhances collaboration and\nstrengthens the company’s presence.","A fusion of Japandi and Industrial design was used to create a balance between warmth, minimalism, and\nfunctionality.","Natural materials, clean LINEAR lines, and soft textures were combined with industrial elements like exposed structures and bold finishes to establish a modern yet welcoming office environment.","The integration of MTN’s brand heritage through\ncurated design details ensured a strong identity throughout the space.","The Collaborative Workspaces serve as the heart of the design, providing dynamic environments where employees can brainstorm, innovate, and create together. These spaces are enhanced with flexible seating, writable surfaces, and advanced technology, allowing for seamless communication and productivity.","The combination of warm woods, raw metals, and sleek finishes creates a sophisticated yet inviting workspace.","Modular acoustic ceiling system, bright brand-colored columns, and sit-stand workstations with privacy screens."]'::jsonb, '/projects/mtn-bayobab-mtn-bayobab-offices-3-15b2960c.jpg', '["/projects/mtn-bayobab-mtn-bayobab-offices-3-15b2960c.jpg"]'::jsonb,
  'tall', '["interior-design"]'::jsonb, false, 12, true
);
