INSERT INTO public.faq_topics (id, slug, label, sort_order, published)
    VALUES ('3f0e5245-78b0-4f2c-af48-bad91855b738', 'about', 'About TwentyOne06', 0, true);
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      '8c5d6fdf-c7a2-49ca-a60c-455b3c8a3680',
      '3f0e5245-78b0-4f2c-af48-bad91855b738',
      'What is TwentyOne06 and where are we based?',
      'TwentyOne06 is a Dubai-based, multi-award-winning interior design and branding studio founded in 2018 by Govind Shepley, Founder and Creative Director.

Named after the apartment where the business began, TwentyOne06 has grown from a one-person design practice into a full-service studio specialising in hospitality, F&B, hotels, retail, and commercial environments across the UAE and GCC.

Today, we bring together Interior Design, Branding, Design Project Management, and Design Strategy & Operations to create spaces, brands, and experiences built around people and designed to perform.',
      '<p>TwentyOne06 is a Dubai-based, multi-award-winning interior design and branding studio founded in 2018 by Govind Shepley, Founder and Creative Director.</p><p>Named after the apartment where the business began, TwentyOne06 has grown from a one-person design practice into a full-service studio specialising in hospitality, F&amp;B, hotels, retail, and commercial environments across the UAE and GCC.</p><p>Today, we bring together Interior Design, Branding, Design Project Management, and Design Strategy &amp; Operations to create spaces, brands, and experiences built around people and designed to perform.</p>',
      NULL,
      NULL,
      0, true
    );
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      '39f69f4f-b2ac-4bf2-ab19-ada285e66315',
      '3f0e5245-78b0-4f2c-af48-bad91855b738',
      'Does TwentyOne06 only do interior design or do we offer other services?',
      'We offer four integrated service lines that work together to deliver a seamless project experience:
• Interior Design
• Branding
• Design Project Management
• Design Strategy & Operations

Our services cover every stage of a project, from concept development and brand positioning to design execution, construction coordination, and post-design support.',
      '<p>We offer four integrated service lines that work together to deliver a seamless project experience:<br/>• Interior Design<br/>• Branding<br/>• Design Project Management<br/>• Design Strategy &amp; Operations</p><p>Our services cover every stage of a project, from concept development and brand positioning to design execution, construction coordination, and post-design support.</p>',
      'Explore our services',
      '/services',
      1, true
    );
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      '4a73493d-731a-4629-a477-82bb8bdf6b67',
      '3f0e5245-78b0-4f2c-af48-bad91855b738',
      'What makes TwentyOne06 different?',
      'What sets TwentyOne06 apart is our ability to bridge design, branding, and project delivery under one roof. Rather than handing over drawings and stepping away, we remain involved throughout the journey, helping clients navigate complex projects with greater clarity, consistency, and confidence. Our approach is built around long-term relationships, operational thinking, and creating spaces that work as well as they look across Dubai, the UAE, and the GCC.',
      '<p>What sets TwentyOne06 apart is our ability to bridge design, branding, and project delivery under one roof. Rather than handing over drawings and stepping away, we remain involved throughout the journey, helping clients navigate complex projects with greater clarity, consistency, and confidence. Our approach is built around long-term relationships, operational thinking, and creating spaces that work as well as they look across Dubai, the UAE, and the GCC.</p>',
      NULL,
      NULL,
      2, true
    );
