    );
INSERT INTO public.faq_topics (id, slug, label, sort_order, published)
    VALUES ('0132bbe5-0975-4956-aeae-ee4fb2b7434e', 'interior-design', 'Interior Design', 1, true);
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      '055df84f-dffe-4944-a9ee-ce3888e8e4ad',
      '0132bbe5-0975-4956-aeae-ee4fb2b7434e',
      'What is included in an interior design project with TwentyOne06?',
      'Our interior design service covers the full arc of a project - from concept development, space planning, and material selection through to technical drawings, visualisations, construction documentation, and on-site supervision. Every scope is tailored to the project, but our commitment is consistent: what was designed is what gets built.',
      '<p>Our interior design service covers the full arc of a project - from concept development, space planning, and material selection through to technical drawings, visualisations, construction documentation, and on-site supervision. Every scope is tailored to the project, but our commitment is consistent: what was designed is what gets built.</p>',
      NULL,
      NULL,
      0, true
    );
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      'a3f54693-13d9-4fda-a702-589bd94f5e44',
      '0132bbe5-0975-4956-aeae-ee4fb2b7434e',
      'How long does an interior design project take?',
      'Timelines vary depending on scale and complexity. A restaurant or F&B interior design project typically runs from 3 to 6 months from brief to handover. A hotel renovation or larger commercial project may run from 6 to 18 months. TwentyOne06 is transparent about timelines from the first conversation - and our Design Project Management service ensures those timelines are protected throughout the build.',
      '<p>Timelines vary depending on scale and complexity. A restaurant or F&amp;B interior design project typically runs from 3 to 6 months from brief to handover. A hotel renovation or larger commercial project may run from 6 to 18 months. TwentyOne06 is transparent about timelines from the first conversation - and our Design Project Management service ensures those timelines are protected throughout the build.</p>',
      NULL,
      NULL,
      1, true
    );
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      '87050498-4640-4dba-ae98-2695eb726a36',
      '0132bbe5-0975-4956-aeae-ee4fb2b7434e',
      'Can TwentyOne06 manage contractors and consultants during construction?',
      'Yes. Through our Design Project Management service, we work directly with contractors, consultants, and suppliers throughout the build - protecting design intent, managing communication, and ensuring the approved design is executed correctly. We do not hand over drawings and disappear.',
      '<p>Yes. Through our Design Project Management service, we work directly with contractors, consultants, and suppliers throughout the build - protecting design intent, managing communication, and ensuring the approved design is executed correctly. We do not hand over drawings and disappear.</p>',
      NULL,
      NULL,
      2, true
    );
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      'd9068b48-3509-40a1-a9f8-ae46aa3120b1',
      '0132bbe5-0975-4956-aeae-ee4fb2b7434e',
      'Can TwentyOne06 remain involved after the design phase is complete?',
      'Absolutely. Many clients engage TwentyOne06 through construction and fit-out to oversee implementation, coordinate stakeholders, review site progress, and ensure the final result reflects the approved design. Long-term client relationships are a core part of how we work - many of our clients return project after project and refer us to others.',
      '<p>Absolutely. Many clients engage TwentyOne06 through construction and fit-out to oversee implementation, coordinate stakeholders, review site progress, and ensure the final result reflects the approved design. Long-term client relationships are a core part of how we work - many of our clients return project after project and refer us to others.</p>',
      NULL,
      NULL,
      3, true
    );
INSERT INTO public.faq_topics (id, slug, label, sort_order, published)
    VALUES ('c5ba9ac6-914c-46f6-a2d7-c136df741477', 'branding', 'Branding', 2, true);
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      'fe795e94-7a29-4ef7-a1dc-6d5295797167',
      'c5ba9ac6-914c-46f6-a2d7-c136df741477',
      'What is included in a branding project with TwentyOne06?',
      'Depending on the scope, branding projects include brand strategy and positioning, naming, visual identity design, signage, environmental graphics, brand guidelines, and wayfinding systems. We work across hospitality, F&B, retail, and commercial sectors in Dubai and the UAE - creating brand identities that work inside the space and beyond it.',
      '<p>Depending on the scope, branding projects include brand strategy and positioning, naming, visual identity design, signage, environmental graphics, brand guidelines, and wayfinding systems. We work across hospitality, F&amp;B, retail, and commercial sectors in Dubai and the UAE - creating brand identities that work inside the space and beyond it.</p>',
      NULL,
      NULL,
      0, true
    );
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      'd18e5faf-6fcc-42fc-ac1a-e77e3c7b7c84',
      'c5ba9ac6-914c-46f6-a2d7-c136df741477',
      'What is the difference between brand strategy and visual identity?',
      'Brand strategy defines how your business is positioned, who it serves, and what makes it different. Visual identity brings that strategy to life - through logos, colour systems, typography, and design frameworks. At TwentyOne06, one always informs the other. We do not design logos without understanding the brand behind them.',
      '<p>Brand strategy defines how your business is positioned, who it serves, and what makes it different. Visual identity brings that strategy to life - through logos, colour systems, typography, and design frameworks. At TwentyOne06, one always informs the other. We do not design logos without understanding the brand behind them.</p>',
      NULL,
      NULL,
      1, true
    );
INSERT INTO public.faq_entries (
