    ) VALUES (
      'b0d016df-67c7-4719-a0ab-5fe2da35790d',
      'c5ba9ac6-914c-46f6-a2d7-c136df741477',
      'How does TwentyOne06 approach branding for hospitality and F&B businesses?',
      'Your space tells a story before anyone reads a word. TwentyOne06''s branding practice makes sure that story is the right one - developing visual identities, naming systems, and environmental graphics that give hospitality and F&B businesses across the UAE and GCC a consistent, distinctive voice across every touchpoint, from the logo on the door to the signage on the wall.',
      '<p>Your space tells a story before anyone reads a word. TwentyOne06''s branding practice makes sure that story is the right one - developing visual identities, naming systems, and environmental graphics that give hospitality and F&amp;B businesses across the UAE and GCC a consistent, distinctive voice across every touchpoint, from the logo on the door to the signage on the wall.</p>',
      NULL,
      NULL,
      2, true
    );
INSERT INTO public.faq_topics (id, slug, label, sort_order, published)
    VALUES ('b58d9558-8ac4-40e7-ad7f-fb73e74a8bd5', 'design-management', 'Design Management', 3, true);
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      'fd490bac-aa23-46d5-a3da-b3f0f1f02bc3',
      'b58d9558-8ac4-40e7-ad7f-fb73e74a8bd5',
      'What is TwentyOne06''s Design Management service?',
      'TwentyOne06 Design Management service provides expert design oversight, local market knowledge, and on-the-ground accountability for hospitality, F&B, hotel, retail, and commercial projects across Dubai, the UAE, and the GCC. From material specification and design coordination to on-site quality review and final sign-off, we connect client, designer, and contractor under one clear direction. Every decision stays true to the design intent and the standards of the market it is being delivered in.',
      '<p>TwentyOne06 Design Management service provides expert design oversight, local market knowledge, and on-the-ground accountability for hospitality, F&amp;B, hotel, retail, and commercial projects across Dubai, the UAE, and the GCC. From material specification and design coordination to on-site quality review and final sign-off, we connect client, designer, and contractor under one clear direction. Every decision stays true to the design intent and the standards of the market it is being delivered in.</p>',
      NULL,
      NULL,
      0, true
    );
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      '4fd9b30b-079a-49b8-ae8b-765ae1f4ea5e',
      'b58d9558-8ac4-40e7-ad7f-fb73e74a8bd5',
      'Who is TwentyOne06''s Design Management service for?',
      'TwentyOne06''s Design Management service is for developers, hotel groups, F&B operators, and international brands who need expert design leadership on their project in Dubai, the UAE, or the wider GCC. Whether you are commissioning a full interior design brief with us or bringing an existing design into the region, our team provides the local market expertise, material knowledge, and design accountability your project needs, delivered without compromise.',
      '<p>TwentyOne06''s Design Management service is for developers, hotel groups, F&amp;B operators, and international brands who need expert design leadership on their project in Dubai, the UAE, or the wider GCC. Whether you are commissioning a full interior design brief with us or bringing an existing design into the region, our team provides the local market expertise, material knowledge, and design accountability your project needs, delivered without compromise.</p>',
      NULL,
      NULL,
      1, true
    );
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      'a0c2de84-0b0c-41cc-a021-303871ea4617',
      'b58d9558-8ac4-40e7-ad7f-fb73e74a8bd5',
      'What makes TwentyOne06''s Design Management service different?',
      'Unlike generalist project management, TwentyOne06''s Design Management service is led by design professionals with deep knowledge of UAE and GCC suppliers, materials, and construction standards. Every design decision is informed by both creative expertise and practical local market knowledge, ensuring hospitality, F&B, retail and commercial projects across Dubai, the UAE and wider GCC are delivered on design, on budget, and on brief.',
      '<p>Unlike generalist project management, TwentyOne06''s Design Management service is led by design professionals with deep knowledge of UAE and GCC suppliers, materials, and construction standards. Every design decision is informed by both creative expertise and practical local market knowledge, ensuring hospitality, F&amp;B, retail and commercial projects across Dubai, the UAE and wider GCC are delivered on design, on budget, and on brief.</p>',
      NULL,
      NULL,
      2, true
    );
INSERT INTO public.faq_topics (id, slug, label, sort_order, published)
    VALUES ('51fe1b49-9977-4a99-a633-0a37b5b0c476', 'design-strategy', 'Design Strategy and Operations', 4, true);
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      'e5edde9f-abc3-427d-a7bd-1c8be87eada0',
      '51fe1b49-9977-4a99-a633-0a37b5b0c476',
      'What is Design Strategy and Operations?',
      'Design Strategy and Operations is for clients who need to define what their space needs to achieve before the design process begins. TwentyOne06 works with hospitality and F&B operators across Dubai and the UAE, Saudi Arabia, and Kuwait, to map the guest experience, assess commercial viability, and establish a clear strategic framework, so the design that follows has a purpose and a measurable outcome.',
      '<p>Design Strategy and Operations is for clients who need to define what their space needs to achieve before the design process begins. TwentyOne06 works with hospitality and F&amp;B operators across Dubai and the UAE, Saudi Arabia, and Kuwait, to map the guest experience, assess commercial viability, and establish a clear strategic framework, so the design that follows has a purpose and a measurable outcome.</p>',
      NULL,
      NULL,
      0, true
    );
INSERT INTO public.faq_entries (
      id, topic_id, question, answer, answer_html, link_label, link_to, sort_order, published
    ) VALUES (
      'ac13d7d6-e942-40ed-a2a8-df4f680c8734',
      '51fe1b49-9977-4a99-a633-0a37b5b0c476',
      'Can TwentyOne06 help develop a restaurant or hospitality concept from scratch?',
      'Yes. TwentyOne06 supports hospitality and F&B concepts from the earliest stages, helping define the customer experience, operational flow, brand positioning, and interior design direction before a brief is written. This service is particularly valuable for developers, hotel groups, and F&B operators who are launching a new concept and want to get the fundamentals right before committing to design.',
      '<p>Yes. TwentyOne06 supports hospitality and F&amp;B concepts from the earliest stages, helping define the customer experience, operational flow, brand positioning, and interior design direction before a brief is written. This service is particularly valuable for developers, hotel groups, and F&amp;B operators who are launching a new concept and want to get the fundamentals right before committing to design.</p>',
      NULL,
      NULL,
      1, true
    );
INSERT INTO public.faq_topics (id, slug, label, sort_order, published)
    VALUES ('4738f44c-4994-42b1-aa17-ba2f06af70e0', 'getting-started', 'Getting Started', 5, true);
INSERT INTO public.faq_entries (
